// TCMS's flow2Notify.ts posts one JSON object per genuinely-new
// RISK_REVIEW_PROPOSED review case (never on an idempotent-replay attach).
// Fail visibly rather than post a broken/blank Teams card on a malformed
// or partial notification.
const body = $input.first().json.body || {};
const required = [
  "organizationId",
  "reviewCaseId",
  "processInstanceId",
  "disposition",
  "documentRef",
  "deepLinkUrl",
];
for (const field of required) {
  const value = body[field];
  if (value === undefined || value === null || value === "") {
    throw new Error(`FLOW2_NOTIFICATION_MISSING_FIELD: ${field}`);
  }
}

const evidenceBasisList = Array.isArray(body.evidenceBasisList)
  ? body.evidenceBasisList
  : [];
const evidenceBasisLine =
  evidenceBasisList.length > 0 ? evidenceBasisList.join(", ") : "n/a";

// v.do (four-eyes FYI-only) and d.do (operational reviewer) both see this
// same card in the same channel -- Flow 2 never DMs one without the other,
// and never requires v.do to act (see HANDOVER_FLOW2.md's role assumption).
const messageHtml =
  "<p><strong>Rechnungspr\u00fcfung: menschliche Pr\u00fcfung angefordert</strong></p>" +
  `<p>Organisation: ${body.organizationId}<br/>` +
  `Vorgang: ${body.processInstanceId}<br/>` +
  `Dokument: ${body.documentRef}<br/>` +
  `Status: ${body.disposition}<br/>` +
  `Evidenzgrundlage: ${evidenceBasisLine}</p>` +
  `<p><a href="${body.deepLinkUrl}">In TCMS \u00f6ffnen</a></p>`;

return [
  {
    json: {
      ...body,
      evidenceBasisList,
      evidenceBasisLine,
      messageHtml,
    },
  },
];
